import React, { useState } from 'react';

export default function ApiLab() {
  const baseUrl = (process.env.REACT_APP_API_URL || 'http://localhost:8080').replace(/\/$/, '');
  const [endpoint, setEndpoint] = useState('/api/cars');
  const [status, setStatus] = useState('idle'); // idle | loading | success | error
  const [statusCode, setStatusCode] = useState(null);
  const [responseData, setResponseData] = useState(null);
  const [errorMessage, setErrorMessage] = useState('');

  const handleTestFetch = async (targetEndpoint = endpoint) => {
    setEndpoint(targetEndpoint);
    setStatus('loading');
    setStatusCode(null);
    setResponseData(null);
    setErrorMessage('');

    try {
      const res = await fetch(`${baseUrl}${targetEndpoint}`);
      setStatusCode(res.status);
      const data = await res.json().catch(() => ({ message: 'No JSON body returned' }));

      if (!res.ok) {
        throw new Error(data.error || data.message || `HTTP Error ${res.status}`);
      }

      setResponseData(data);
      setStatus('success');
    } catch (err) {
      setErrorMessage(err.message);
      setStatus('error');
    }
  };

  return (
    <div className="max-w-4xl mx-auto py-8 space-y-6 text-slate-900">
      <div>
        <h1 className="text-3xl font-extrabold mb-2">API Lab (ทดสอบเชื่อมต่อ Go Backend)</h1>
        <p className="text-sm text-gray-600">
          Base URL ปัจจุบัน: <code className="bg-blue-50 text-[#1d64f2] px-2 py-0.5 rounded font-mono">{baseUrl}</code>
        </p>
      </div>

      {/* ปุ่มทดสอบด่วน */}
      <div className="flex flex-wrap gap-2">
        <button
          onClick={() => handleTestFetch('/api/cars')}
          className="text-xs bg-blue-50 text-[#1d64f2] border border-blue-200 px-3 py-1.5 rounded-lg font-semibold hover:bg-blue-100"
        >
          GET /api/cars
        </button>
        <button
          onClick={() => handleTestFetch('/api/cars/1')}
          className="text-xs bg-blue-50 text-[#1d64f2] border border-blue-200 px-3 py-1.5 rounded-lg font-semibold hover:bg-blue-100"
        >
          GET /api/cars/1
        </button>
        <button
          onClick={() => handleTestFetch('/health')}
          className="text-xs bg-blue-50 text-[#1d64f2] border border-blue-200 px-3 py-1.5 rounded-lg font-semibold hover:bg-blue-100"
        >
          GET /health
        </button>
      </div>

      {/* ช่องกรอก Endpoint เอง */}
      <div className="flex gap-3 bg-white p-4 rounded-2xl border border-gray-200 shadow-sm">
        <span className="bg-gray-100 text-gray-700 font-bold text-sm px-3 py-2 rounded-xl flex items-center">
          GET
        </span>
        <input
          type="text"
          value={endpoint}
          onChange={(e) => setEndpoint(e.target.value)}
          placeholder="/api/cars"
          className="flex-1 border border-gray-200 rounded-xl px-3.5 py-2 text-sm font-mono focus:outline-none focus:border-[#1d64f2]"
        />
        <button
          onClick={() => handleTestFetch(endpoint)}
          disabled={status === 'loading'}
          className="bg-[#1d64f2] text-white font-semibold px-6 py-2 rounded-xl text-sm hover:bg-blue-700 transition disabled:opacity-50"
        >
          {status === 'loading' ? 'กำลังส่ง...' : 'ส่ง Request'}
        </button>
      </div>

      {/* แสดงสถานะ Loading / Error / Success */}
      <div className="bg-white rounded-2xl border border-gray-200 p-6 shadow-sm space-y-4">
        <div className="flex items-center justify-between">
          <h2 className="font-bold text-base">ผลลัพธ์จากเซิร์ฟเวอร์</h2>
          <div className="flex items-center gap-2 text-xs font-bold">
            {status === 'loading' && <span className="bg-yellow-100 text-yellow-800 px-3 py-1 rounded-full">Loading...</span>}
            {status === 'success' && <span className="bg-green-100 text-green-700 px-3 py-1 rounded-full">Success ({statusCode})</span>}
            {status === 'error' && <span className="bg-red-100 text-red-700 px-3 py-1 rounded-full">Error {statusCode ? `(${statusCode})` : ''}</span>}
          </div>
        </div>

        {status === 'idle' && (
          <p className="text-sm text-gray-400">กดปุ่ม "ส่ง Request" เพื่อทดสอบการดึงข้อมูลจาก API</p>
        )}

        {status === 'error' && (
          <div className="bg-red-50 border border-red-200 text-red-700 p-4 rounded-xl text-sm">
            <strong>เกิดข้อผิดพลาด:</strong> {errorMessage}
          </div>
        )}

        {status === 'success' && (
          <pre className="bg-slate-900 text-green-400 p-4 rounded-xl text-xs overflow-x-auto max-h-96 font-mono">
            {JSON.stringify(responseData, null, 2)}
          </pre>
        )}
      </div>
    </div>
  );
}
